const API=API_BASE_URL;type Tab="Overview"|"Sitemap"|"JavaScript"|"Security"|"Browser Jobs"|"Reconstruction"|"Repository"|"Correlation";
function websiteEvidence(scan:ScanResult):CommonSecurityFinding[]{
 if(scan.security_findings?.length)return scan.security_findings;
 return scan.findings.map(f=>({finding_id:`legacy-${f.id}`,check_id:f.id,source:"website",target:scan.final_url,location:{kind:"url" as const,value:scan.final_url},title:f.title,category:"security-configuration",severity:f.severity,confidence:f.confidence,validation_state:"observed" as const,evidence:f.evidence,impact:null,preconditions:[],remediation:f.recommendation,scanner_version:"legacy",scope_id:null,observed_at:scan.scanned_at}));
}
function repositoryEvidence(report:RepositoryReport):CommonSecurityFinding[]{
 if(report.security_findings?.length)return report.security_findings;
 return report.findings.map(f=>({finding_id:`legacy-${f.id}-${f.path}-${f.line}`,check_id:f.id,source:"repository",target:report.repository,location:{kind:"file" as const,path:f.path,line:f.line},title:f.title,category:f.category,severity:f.severity,confidence:f.confidence,validation_state:f.validation_state,evidence:f.evidence,impact:null,preconditions:[],remediation:f.recommendation,scanner_version:report.scanner_version,scope_id:null}));
}
function findingLocation(f:CommonSecurityFinding):string{
 return f.location.kind==="url"?f.location.value:`${f.location.path}${f.location.line?":"+f.location.line:""}`;
}
export default function App(){
 const[url,setUrl]=useState(""),[scopePaths,setScopePaths]=useState("/"),[siteAuthorised,setSiteAuthorised]=useState(false),[scan,setScan]=useState<ScanResult|null>(null),[busy,setBusy]=useState(false),[error,setError]=useState(""),[tab,setTab]=useState<Tab>("Overview"),[query,setQuery]=useState(""),[detail,setDetail]=useState<{title:string;body:string}|null>(null),[history,setHistory]=useState<ScanHistoryItem[]>([]),[maxPages,setMaxPages]=useState(8),[repoFile,setRepoFile]=useState<File|null>(null),[repoAuthorised,setRepoAuthorised]=useState(false),[repoBusy,setRepoBusy]=useState(false),[repoReport,setRepoReport]=useState<RepositoryReport|null>(null),[githubUrl,setGithubUrl]=useState(""),[githubRef,setGithubRef]=useState(""),[githubAuthorised,setGithubAuthorised]=useState(false),[githubBusy,setGithubBusy]=useState(false),[advisoryBusy,setAdvisoryBusy]=useState(false),[advisoryReport,setAdvisoryReport]=useState<AdvisoryReport|null>(null),[authorizedTargets,setAuthorizedTargets]=useState<AuthorizedTarget[]>([]),[targetHostname,setTargetHostname]=useState(""),[targetPorts,setTargetPorts]=useState("443, 80"),[targetId,setTargetId]=useState(""),[targetChallenge,setTargetChallenge]=useState<TargetChallenge|null>(null),[targetBusy,setTargetBusy]=useState(false),[browserJobs,setBrowserJobs]=useState<BrowserJob[]>([]),[selectedBrowserJobId,setSelectedBrowserJobId]=useState(""),[selectedBrowserJob,setSelectedBrowserJob]=useState<BrowserJob|null>(null),[browserJobBusy,setBrowserJobBusy]=useState(false),[browserMaxRequests,setBrowserMaxRequests]=useState(80);
 const webEvidence=useMemo(()=>scan?websiteEvidence(scan):[],[scan]);const repoEvidence=useMemo(()=>repoReport?repositoryEvidence(repoReport):[],[repoReport]);const routeCorrelation=useMemo(()=>scan&&repoReport?correlateWebsiteAndRepository(scan,repoReport):null,[scan,repoReport]);
 async function refreshHistory(){try{const d=await apiRequest<{items:ScanHistoryItem[]}>(`${API}/api/scans?limit=12`);setHistory(Array.isArray(d.items)?d.items:[]);}catch{/* History is optional while the API is offline. */}}
 async function refreshBrowserJobs(){try{const d=await apiRequest<{items:BrowserJob[]}>(`${API}/api/browser-jobs?limit=30`);setBrowserJobs(Array.isArray(d.items)?d.items:[]);}catch{/* Browser jobs are unavailable when the worker queue is not configured. */}}
 async function loadBrowserJob(id:string){try{const job=await apiRequest<BrowserJob>(`${API}/api/browser-jobs/${encodeURIComponent(id)}`);setSelectedBrowserJob(job);setBrowserJobs(items=>items.map(item=>item.job_id===id?{...item,...job,result:undefined}:item));}catch(e){setError(e instanceof Error?e.message:"Could not load browser job details.");}}
 async function submitBrowserJob(){if(!url.trim()||!targetId||!siteAuthorised)return;setBrowserJobBusy(true);setError("");try{const job=await apiRequest<BrowserJob>(`${API}/api/browser-jobs`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({url:url.trim(),target_id:targetId,scope_paths:scopePaths.split(",").map(path=>path.trim()).filter(Boolean).length?scopePaths.split(",").map(path=>path.trim()).filter(Boolean):["/"],max_requests:browserMaxRequests,authorised:true})});setSelectedBrowserJobId(job.job_id);setSelectedBrowserJob(job);setBrowserJobs(items=>[job,...items.filter(item=>item.job_id!==job.job_id)]);await refreshBrowserJobs();}catch(e){setError(e instanceof Error?e.message:"Could not queue browser job.");}finally{setBrowserJobBusy(false);}}
 async function cancelBrowserJob(id:string){setBrowserJobBusy(true);setError("");try{await apiRequest(`${API}/api/browser-jobs/${encodeURIComponent(id)}/cancel`,{method:"POST"});await refreshBrowserJobs();await loadBrowserJob(id);}catch(e){setError(e instanceof Error?e.message:"Could not cancel browser job.");}finally{setBrowserJobBusy(false);}}
 async function refreshTargets(){try{const d=await apiRequest<{items:AuthorizedTarget[]}>(`${API}/api/targets`);const items=Array.isArray(d.items)?d.items:[];setAuthorizedTargets(items);if(targetId&&!items.some(item=>item.target_id===targetId))setTargetId("");}catch{/* Target authorizations are optional in local preview mode. */}}
 async function createTargetChallenge(){setTargetBusy(true);setError("");setTargetChallenge(null);try{const ports=targetPorts.split(",").map(value=>Number(value.trim())).filter(value=>Number.isInteger(value)&&value>0&&value<=65535);const paths=scopePaths.split(",").map(value=>value.trim()).filter(Boolean);const result=await apiRequest<TargetChallenge>(`${API}/api/targets/challenges`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({hostname:targetHostname,ports,scope_paths:paths.length?paths:["/"]})});setTargetChallenge(result);}catch(e){setError(e instanceof Error?e.message:"Could not create target verification challenge.");}finally{setTargetBusy(false);}}
 async function verifyTargetChallenge(){if(!targetChallenge)return;setTargetBusy(true);setError("");try{const target=await apiRequest<AuthorizedTarget>(`${API}/api/targets/challenges/${encodeURIComponent(targetChallenge.challenge_id)}/verify`,{method:"POST"});setTargetId(target.target_id);setScopePaths(target.scope_paths.join(", "));setTargetChallenge(null);await refreshTargets();}catch(e){setError(e instanceof Error?e.message:"DNS verification failed.");}finally{setTargetBusy(false);}}
 async function revokeTargetAuthorization(){if(!targetId)return;setTargetBusy(true);setError("");try{await apiRequest(`${API}/api/targets/${encodeURIComponent(targetId)}/revoke`,{method:"POST"});setTargetId("");await refreshTargets();}catch(e){setError(e instanceof Error?e.message:"Could not revoke target authorization.");}finally{setTargetBusy(false);}}

 useEffect(()=>{void refreshHistory();void refreshTargets();void refreshBrowserJobs();},[]);
 useEffect(()=>{if(!browserJobs.some(job=>job.status==="queued"||job.status==="running"))return;const timer=window.setInterval(()=>{void refreshBrowserJobs();if(selectedBrowserJobId)void loadBrowserJob(selectedBrowserJobId);},2500);return()=>window.clearInterval(timer);},[browserJobs,selectedBrowserJobId]);
 async function openSavedScan(id:string){setError("");try{const d=await apiRequest<ScanResult>(`${API}/api/scans/${encodeURIComponent(id)}`);setScan(d);setUrl(d.requested_url);setScopePaths(d.scope_paths?.join(", ")||"/");setTargetId(d.target_id||"");setTab("Overview");setQuery("");}catch(e){setError(e instanceof Error?e.message:"Could not load saved scan.");}}
 async function run(e:FormEvent){e.preventDefault();setBusy(true);setError("");try{const d=await apiRequest<ScanResult>(`${API}/api/scans`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({url,max_pages:maxPages,authorised:siteAuthorised,target_id:targetId||null,scope_paths:(scopePaths.split(",").map(path=>path.trim()).filter(Boolean).length?scopePaths.split(",").map(path=>path.trim()).filter(Boolean):["/"])})});if(!d||typeof d.id!=="string")throw Error("The API returned an invalid scan response.");setScan(d);setTab("Overview");setQuery("");await refreshHistory();}catch(e){setError(e instanceof TypeError?"Cannot reach the UnWeb API. Start the FastAPI backend and try again.":e instanceof Error?e.message:"API connection failed.");}finally{setBusy(false);}}
 async function runRepository(e:FormEvent){e.preventDefault();if(!repoFile||!repoAuthorised)return;setRepoBusy(true);setError("");setRepoReport(null);try{const report=await apiRequest<RepositoryReport>(API+"/api/repository-scans",{method:"POST",headers:{"Content-Type":repoFile.type||"application/zip","X-UnWeb-Authorised":"true","X-Repository-Filename":encodeURIComponent(repoFile.name)},body:repoFile});if(!report||!Array.isArray(report.findings)||!Array.isArray(report.dependency_inventory))throw Error("The API returned an invalid repository report.");setRepoReport(report);}catch(e){setError(e instanceof TypeError?"Cannot reach the UnWeb API. Start the FastAPI backend and try again.":e instanceof Error?e.message:"Repository analysis failed.");}finally{setRepoBusy(false);}}
 async function runDependencyAdvisories(){if(!repoReport||(!repoAuthorised&&!githubAuthorised))return;const packages=repoReport.dependency_inventory.filter(d=>d.source_type==="lockfile"&&d.resolved_version).map(d=>({name:d.name,ecosystem:d.ecosystem,version:d.resolved_version!})).slice(0,100);if(!packages.length){setError("No lockfile-resolved dependency versions are available for advisory lookup.");return;}setAdvisoryBusy(true);setAdvisoryReport(null);setError("");try{const result=await apiRequest<AdvisoryReport>("/api/dependency-advisories",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({authorised:true,packages})});setAdvisoryReport(result);}catch(e){setError(e instanceof TypeError?"Cannot reach the UnWeb API. Start the FastAPI backend and try again.":e instanceof Error?e.message:"Dependency advisory lookup failed.");}finally{setAdvisoryBusy(false);}}
 async function runGithubRepository(e:FormEvent){e.preventDefault();if(!githubUrl.trim()||!githubAuthorised)return;setGithubBusy(true);setError("");setRepoReport(null);try{const report=await apiRequest<RepositoryReport>(API+"/api/github-repository-scans",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({repository_url:githubUrl.trim(),ref:githubRef.trim()||null,authorised:true})});if(!report||!Array.isArray(report.findings)||!Array.isArray(report.dependency_inventory)||!report.source?.commit_sha)throw Error("The API returned an invalid GitHub repository report.");setRepoReport(report);}catch(e){setError(e instanceof TypeError?"Cannot reach the UnWeb API. Start the FastAPI backend and try again.":e instanceof Error?e.message:"GitHub repository analysis failed.");}finally{setGithubBusy(false);}}
 const assets=useMemo(()=>scan?.assets.filter(a=>`${a.kind} ${a.url}`.toLowerCase().includes(query.toLowerCase()))||[],[scan,query]);
 function download(content:string,name:string,type="text/plain"){const b=new Blob([content],{type});const a=document.createElement("a");a.href=URL.createObjectURL(b);a.download=name;a.click();window.setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
 const tabs:[Tab,ReactNode][]=[["Overview",<Activity size={15}/>],["Sitemap",<Network size={15}/>],["JavaScript",<Braces size={15}/>],["Security",<ShieldCheck size={15}/>],["Browser Jobs",<MonitorPlay size={15}/>],["Repository",<FileUp size={15}/>],["Correlation",<GitBranch size={15}/>],["Reconstruction",<Layers3 size={15}/>]];
 return <div className="shell"><header className="topbar"><div className="brand"><span className="mark"><Layers3 size={17}/></span><b>UnWeb</b><small>PREVIEW 0.2</small></div><div className="scan-controls"><form className="urlbar" onSubmit={run}><Globe2 size={15}/><input aria-label="Website URL" value={url} onChange={e=>setUrl(e.target.value)} placeholder="Enter a website URL you are authorised to analyse…"/><select className="page-limit" aria-label="Maximum pages to scan" value={maxPages} onChange={e=>setMaxPages(Number(e.target.value))}><option value={4}>4 pages</option><option value={8}>8 pages</option><option value={12}>12 pages</option><option value={20}>20 pages</option><option value={30}>30 pages</option></select>{url&&<button type="button" className="icon" onClick={()=>setUrl("")} aria-label="Clear URL"><X size={14}/></button>}<button className="run" disabled={busy||!url.trim()||!siteAuthorised}>{busy?"Analysing…":<>Analyse <kbd>↵</kbd></>}</button></form><label className="url-consent"><input type="checkbox" checked={siteAuthorised} onChange={e=>setSiteAuthorised(e.target.checked)}/> I own this site or have explicit permission to assess it.</label><label className="scope-control">PATH SCOPE<input aria-label="Approved path prefixes" value={scopePaths} onChange={e=>setScopePaths(e.target.value)} placeholder="/, /api/v1" title="Comma-separated approved URL path prefixes"/></label><details className="target-authorization"><summary>Target ownership verification · {authorizedTargets.length} verified</summary><div className="target-auth-content"><p>Production scans require DNS proof that you control the exact hostname. The authorization is limited to the selected ports and path prefixes and expires after 30 days.</p><div className="target-auth-fields"><label>DOMAIN<input value={targetHostname} onChange={e=>setTargetHostname(e.target.value)} placeholder="example.com"/></label><label>PORTS<input value={targetPorts} onChange={e=>setTargetPorts(e.target.value)} placeholder="443, 80"/></label><button type="button" className="download-code" disabled={targetBusy||!targetHostname.trim()} onClick={createTargetChallenge}>{targetBusy?"Working…":"Generate DNS challenge"}</button></div>{targetChallenge&&<div className="dns-challenge"><b>Add this DNS TXT record</b><small>Record name</small><code>{targetChallenge.record_name}</code><small>TXT value</small><code>{targetChallenge.record_value}</code><small>Expires {new Date(targetChallenge.expires_at).toLocaleString()}</small><button type="button" className="download-code" disabled={targetBusy} onClick={verifyTargetChallenge}>Verify DNS record</button></div>}<div className="target-auth-select"><label>VERIFIED TARGET<select aria-label="Verified target" value={targetId} onChange={e=>{setTargetId(e.target.value);const target=authorizedTargets.find(item=>item.target_id===e.target.value);if(target)setScopePaths(target.scope_paths.join(", "));}}><option value="">No verified target selected</option>{authorizedTargets.map(target=><option key={target.target_id} value={target.target_id}>{target.hostname} · ports {target.ports.join(",")}</option>)}</select></label><button type="button" className="download-code" disabled={targetBusy||!targetId} onClick={revokeTargetAuthorization}>Revoke selected</button></div></div></details></div><button className="export" disabled={!scan} onClick={()=>scan&&download(JSON.stringify(scan,null,2),`unweb-${scan.id}.json`,"application/json")}><Download size={14}/> Export</button></header>
 <div className="layout"><aside className="sidebar"><label>WORKSPACE</label><div className="target"><Globe2 size={16}/><span><b>{scan?new URL(scan.final_url).hostname:"No target selected"}</b><small>{scan?"Analysis complete":"Start with a URL above"}</small></span><ChevronDown size={13}/></div><label className="section-label">ANALYSIS</label>{tabs.map(([name,icon])=><button key={name} onClick={()=>setTab(name)} className={`nav ${tab===name?"active":""}`}>{icon}{name}{name==="Security"&&scan&&<small>{scan.findings.length}</small>}</button>)}<div className="history-block"><label>RECENT SCANS</label>{history.slice(0,6).map(item=><button type="button" className={`history-item ${scan?.id===item.id?"selected":""}`} key={item.id} onClick={()=>openSavedScan(item.id)}><b>{item.title||new URL(item.final_url).hostname}</b><small>{new URL(item.final_url).pathname||"/"}</small></button>)}{history.length===0&&<p className="history-empty">Scans you run will appear here.</p>}</div><div className="sidebar-foot"><LockKeyhole size={15}/><span><b>Passive analysis</b><small>Access controls are not bypassed.</small></span></div></aside>
 <main className="main"><div className="heading"><div><div className="crumb">WORKSPACE / {tab.toUpperCase()}</div><h1>{tab}</h1><p>{({Overview:"A concise view of observable website evidence.",Sitemap:"Pages discovered by the bounded same-origin crawler.",JavaScript:"Public script inventory and conservative source clues.",Security:"Passive security observations with explicit evidence.",Reconstruction:"An editable React starting point from observed content.",Repository:"Read-only analysis of an authorised repository ZIP.",Correlation:"Compare observed website paths with literal routes in an analysed repository.", "Browser Jobs":"Queue isolated Chromium renders, follow live status, and inspect captured DOM and network evidence."} as Record<Tab,string>)[tab]}</p></div>{scan&&<span className="complete">● COMPLETE · {new Date(scan.scanned_at).toLocaleTimeString()}</span>}</div>
 {error&&<div className="error"><CircleAlert size={16}/><span>{error}</span><button onClick={()=>setError("")}><X size={14}/></button></div>}

 {tab==="Browser Jobs"&&<div className="stack">
  <Panel title="Queue a browser intelligence render" badge="ISOLATED CHROMIUM" icon={<MonitorPlay size={15}/>}>
   <p className="notice">Browser jobs perform one unauthenticated render. They do not log in, submit forms, or interact with accounts. Select a DNS-verified target above and confirm authorization before queueing.</p>
   <div className="browser-job-launch">
    <div className="browser-job-launch-meta"><span><b>Target</b><small>{url.trim()||"Enter a URL in the top bar"}</small></span><span><b>Verified authorization</b><small>{authorizedTargets.find(item=>item.target_id===targetId)?.hostname||"No verified target selected"}</small></span></div>
    <label className="repo-file-label">MAXIMUM NETWORK REQUESTS <select className="browser-limit" aria-label="Maximum browser requests" value={browserMaxRequests} onChange={e=>setBrowserMaxRequests(Number(e.target.value))}><option value={20}>20 requests</option><option value={40}>40 requests</option><option value={80}>80 requests</option><option value={120}>120 requests</option><option value={150}>150 requests</option></select></label>
    <label className="repo-consent"><input type="checkbox" checked={siteAuthorised} onChange={e=>setSiteAuthorised(e.target.checked)}/> I own this website or have explicit permission to assess it.</label>
    <div className="repo-actions"><button className="run" disabled={browserJobBusy||!url.trim()||!targetId||!siteAuthorised} onClick={submitBrowserJob}>{browserJobBusy?"Queueing…":"Queue browser render"}</button><small>HTTPS only · verified target required · 45-second render limit</small></div>
   </div>
  </Panel>
  <div className="browser-job-columns">
   <Panel title="Recent browser jobs" badge={browserJobs.length+" JOBS"} icon={<Clock3 size={15}/>}>
    <div className="browser-job-toolbar"><span>Automatically refreshes while jobs are queued or running.</span><button className="icon" type="button" onClick={()=>{void refreshBrowserJobs();}} aria-label="Refresh browser jobs"><RefreshCw size={14}/></button></div>
    {browserJobs.map(job=><button type="button" key={job.job_id} className={"browser-job-row "+(selectedBrowserJobId===job.job_id?"selected":"")} onClick={()=>{setSelectedBrowserJobId(job.job_id);void loadBrowserJob(job.job_id);}}><span className={"job-status "+job.status}>{job.status==="completed"?<CircleCheck size={13}/>:job.status==="failed"?<CircleX size={13}/>:job.status==="running"?<LoaderCircle size={13}/>:<Clock3 size={13}/>} {job.status.toUpperCase()}</span><span className="browser-job-row-main"><b>{job.url}</b><small>{new Date(job.created_at).toLocaleString()} · {job.max_requests} request cap</small></span><ArrowUpRight size={14}/></button>)}
    {!browserJobs.length&&<p className="quiet">No browser jobs yet. Queue a render above to start collecting browser evidence.</p>}
   </Panel>
   <Panel title="Job details and evidence" badge={selectedBrowserJob?selectedBrowserJob.status.toUpperCase():"SELECT A JOB"} icon={<Activity size={15}/>}>
    {!selectedBrowserJob?<p className="quiet">Choose a job from the list to inspect its progress and results.</p>:<div className="browser-job-detail">
     <div className="browser-job-detail-head"><span><b>{selectedBrowserJob.url}</b><small>Job {selectedBrowserJob.job_id}</small></span>{selectedBrowserJob.status==="queued"&&<button type="button" className="download-code" disabled={browserJobBusy} onClick={()=>cancelBrowserJob(selectedBrowserJob.job_id)}><Ban size={13}/> Cancel queued job</button>}</div>
     <div className="job-timeline"><span><small>CREATED</small><b>{new Date(selectedBrowserJob.created_at).toLocaleTimeString()}</b></span><span><small>STARTED</small><b>{selectedBrowserJob.started_at?new Date(selectedBrowserJob.started_at).toLocaleTimeString():"—"}</b></span><span><small>FINISHED</small><b>{selectedBrowserJob.finished_at?new Date(selectedBrowserJob.finished_at).toLocaleTimeString():"—"}</b></span></div>
     {selectedBrowserJob.status==="queued"&&<p className="notice">Waiting for an isolated browser worker to claim this job.</p>}
     {selectedBrowserJob.status==="running"&&<p className="notice">Chromium is rendering the target. This panel refreshes automatically.</p>}
     {selectedBrowserJob.status==="failed"&&<p className="error browser-inline-error">Browser job failed: {selectedBrowserJob.error_code||"UnknownError"}</p>}
     {selectedBrowserJob.status==="cancelled"&&<p className="quiet">This queued job was cancelled before execution.</p>}
     {selectedBrowserJob.result&&<BrowserEvidence result={selectedBrowserJob.result}/>}
    </div>}
   </Panel>
  </div>
 </div>}
 {tab==="Repository"?<div className="stack"><Panel title="Connect a public GitHub repository" badge="PUBLIC SOURCE · READ-ONLY" icon={<Code2 size={15}/> }><p className="notice">Enter a public GitHub repository URL. UnWeb resolves the selected branch or tag to an immutable commit SHA, downloads a bounded source archive, and analyses it without running project code or installing dependencies. Private repositories and GitHub sign-in are not enabled in this preview.</p><form className="repo-form" onSubmit={runGithubRepository}><label className="repo-file-label">GITHUB REPOSITORY URL<input className="repo-text-input" type="url" required value={githubUrl} onChange={e=>{setGithubUrl(e.target.value);setRepoReport(null);}} placeholder="https://github.com/owner/repository"/></label><label className="repo-file-label">BRANCH OR TAG (OPTIONAL)<input className="repo-text-input" type="text" maxLength={255} value={githubRef} onChange={e=>{setGithubRef(e.target.value);setRepoReport(null);}} placeholder="Default branch if blank"/></label><label className="repo-consent"><input type="checkbox" checked={githubAuthorised} onChange={e=>setGithubAuthorised(e.target.checked)}/> I own this repository or have explicit permission to assess it.</label><div className="repo-actions"><button className="run" disabled={githubBusy||!githubUrl.trim()||!githubAuthorised}>{githubBusy?"Resolving commit and analysing…":"Analyse GitHub repository"}</button><small>Public repositories only · 50 MB maximum</small></div><p className="quiet">The report records the exact commit SHA. Findings are heuristic and marked suspected. Exact lockfile-resolved versions can be checked against OSV advisories.</p></form></Panel><Panel title="Or upload a repository archive" badge="LOCAL ZIP" icon={<FileUp size={15}/> }><p className="notice">Use this option for a local export or a private repository archive. The archive is analysed temporarily and deleted after the report is generated.</p><form className="repo-form" onSubmit={runRepository}><label className="repo-file-label">REPOSITORY ZIP<input type="file" accept=".zip,application/zip,application/x-zip-compressed" onChange={e=>{setRepoFile(e.target.files?.[0]||null);setRepoReport(null);}}/></label><label className="repo-consent"><input type="checkbox" checked={repoAuthorised} onChange={e=>setRepoAuthorised(e.target.checked)}/> I own this repository or have explicit permission to assess it.</label><div className="repo-actions"><button className="run" disabled={repoBusy||!repoFile||!repoAuthorised}>{repoBusy?"Analysing…":"Analyse repository"}</button><small>{repoFile?repoFile.name+" · "+(repoFile.size/1024/1024).toFixed(2)+" MB":"ZIP files only · 50 MB maximum"}</small></div><p className="quiet">Results are heuristic and marked suspected. Exact lockfile-resolved versions can be checked against OSV advisories; manifest ranges are not guessed.</p></form></Panel>{repoReport&&<><div className="metrics"><Metric label="FILES SCANNED" value={String(repoReport.files_scanned)} detail={repoReport.truncated?"Scan limits reached":"Bounded source inventory"}/><Metric label="SECURITY INDICATORS" value={String(repoReport.findings.length)} detail="Suspected, needs review"/><Metric label="DEPENDENCIES" value={String(repoReport.dependency_count)} detail="Declared or lockfile resolved"/><Metric label="BYTES ANALYSED" value={(repoReport.bytes_scanned/1024).toFixed(1)+" KB"} detail={repoReport.skipped_files+" files skipped"}/></div><Panel title="Repository assessment" badge={repoReport.repository.toUpperCase()} icon={<ShieldCheck size={15}/>}><div className="repo-actions"><span className="quiet">Scanner {repoReport.scanner_version} · {repoReport.truncated?"Partial report":"Completed within limits"}{repoReport.source&&<> · Commit {repoReport.source.commit_sha.slice(0,12)}</>}</span><button className="download-code" onClick={()=>download(JSON.stringify(repoReport,null,2),"unweb-repository-"+repoReport.repository+".json","application/json")}><Download size={14}/> Export report</button><button className="download-code" onClick={()=>download(JSON.stringify(repositoryReportToSarif(repoReport),null,2),"unweb-"+repoReport.repository+".sarif","application/sarif+json")}><Download size={14}/> Export SARIF</button></div>{repoEvidence.map((f,index)=><button className="security-row" key={f.finding_id+"-"+index} onClick={()=>setDetail({title:f.title,body:"Source: "+f.source+"\nSeverity: "+f.severity+"\nConfidence: "+f.confidence+"\nValidation: "+f.validation_state+"\nLocation: "+findingLocation(f)+"\nRule: "+f.check_id+"\n\nEvidence:\n"+f.evidence+"\n\nImpact: "+(f.impact||"Not established")+"\n\nRemediation:\n"+f.remediation})}><em className={f.severity}>{f.severity.toUpperCase()}</em><span><b>{f.title}</b><small>{findingLocation(f)} · {f.category} · {f.validation_state} · {f.confidence} confidence</small></span><ArrowUpRight size={14}/></button>)}{!repoEvidence.length&&<p className="quiet">No configured rule matched. This does not prove the repository is free of security weaknesses.</p>}</Panel><Panel title="Repository route inventory" badge={`${repoReport.route_count??repoReport.route_inventory?.length??0} ROUTES`} icon={<Network size={15}/>}><p className="notice">Literal route declarations found in source. These are code clues, not proof that an endpoint is deployed, reachable, or protected in a particular way. Dynamic paths and router composition are not resolved.</p>{repoReport.route_inventory?.slice(0,500).map((route,index)=><div className="dependency-row" key={route.method+"-"+route.path+"-"+route.source_path+"-"+route.line+"-"+index}><span><b>{route.method} {route.path}</b><small>{route.source_path}:{route.line} · {route.syntax}</small></span></div>)}{repoReport.route_inventory_truncated&&<p className="notice">Route inventory reached its 2,000-record cap. Additional routes may be omitted; export and inspect the source repository for complete coverage.</p>}{!repoReport.route_inventory?.length&&<p className="quiet">No supported literal route declarations were detected. This does not mean the repository has no routes.</p>}</Panel><Panel title="Dependency inventory" badge={String(repoReport.dependency_count)+" PACKAGES"} icon={<Package size={15}/> }><p className="notice">Inventory only: a listed version is not a vulnerability finding. OSV advisory lookup uses exact versions from lockfiles; manifest constraints are not guessed.</p><div className="repo-actions"><button className="run" onClick={()=>void runDependencyAdvisories()} disabled={advisoryBusy||(!repoAuthorised&&!githubAuthorised)||!repoReport.dependency_inventory.some(d=>d.source_type==="lockfile"&&d.resolved_version)}>{advisoryBusy?"Checking OSV…":"Check resolved versions against OSV"}</button><small>Up to 100 lockfile-resolved packages</small></div>{advisoryReport&&<div className="metrics"><Metric label="PACKAGES CHECKED" value={String(advisoryReport.packages_checked)} detail="Exact resolved versions"/><Metric label="PACKAGES WITH MATCHES" value={String(advisoryReport.packages_with_advisories)} detail="Review upstream records"/><Metric label="ADVISORY MATCHES" value={String(advisoryReport.advisory_matches)} detail="Not an exploitability verdict"/></div>}{advisoryReport?.results.flatMap(item=>item.advisories.map(advisory=><div className="dependency-row" key={item.ecosystem+"-"+item.package+"-"+advisory.id}><span><b>{advisory.id} · {item.package}@{item.version}</b><small>{advisory.summary||"No summary supplied"} · {item.ecosystem}</small>{advisory.references.map(url=><a href={url} target="_blank" rel="noreferrer" key={url}>Upstream advisory ↗</a>)}</span></div>))}{advisoryReport?.results.every(item=>item.advisory_count===0)&&<p className="quiet">OSV returned no matching advisories for these versions. This does not prove the packages are secure.</p>}{advisoryReport&&<p className="notice">{advisoryReport.limitations.join(" ")}</p>}{repoReport.dependency_inventory_truncated&&<p className="notice">The inventory reached the 5,000-record cap. Additional dependencies may be omitted; treat this report as partial and inspect the remaining manifest or lockfile entries separately.</p>}{repoReport.dependency_inventory.slice(0,500).map((d,index)=><div className="dependency-row" key={d.ecosystem+"-"+d.name+"-"+d.source_path+"-"+index}><span><b>{d.name}</b><small>{d.ecosystem} · {d.source_path} · {d.source_type} · {d.dependency_group}</small></span><code>{d.resolved_version||d.version_constraint||"Version unspecified"}</code></div>)}{repoReport.dependency_inventory.length>500&&<p className="quiet">Showing first 500 dependencies. Export the JSON report for the full inventory.</p>}{!repoReport.dependency_inventory.length&&<p className="quiet">No supported dependency manifest or lockfile entries were found.</p>}</Panel><Panel title="Analysis limitations" badge="IMPORTANT" icon={<CircleAlert size={15}/> }>{repoReport.limitations.map((item,index)=><p className="notice" key={index}>{item}</p>)}</Panel></>}</div>:tab==="Correlation"?<div className="stack"><Panel title="Website ↔ repository route overlap" badge={routeCorrelation?String(routeCorrelation.matches.length)+" MATCHES":"NEEDS BOTH SCANS"} icon={<GitBranch size={15}/>}>{!scan||!repoReport?<p className="notice">Run an authorised website scan and an authorised repository analysis first. UnWeb compares observed GET page paths and JavaScript route clues with the repository's bounded literal route inventory.</p>:<><p className="notice">This is a path-overlap view, not a vulnerability verdict. A match does not prove the website runs this repository version, that the path is reachable, or that its authentication and authorisation are correct.</p><div className="metrics"><Metric label="WEBSITE PAGES" value={String(routeCorrelation?.websitePageCount??0)} detail="Fetched using GET"/><Metric label="SCRIPT ROUTE CLUES" value={String(routeCorrelation?.websiteScriptRouteCount??0)} detail="Lexical references"/><Metric label="REPOSITORY ROUTES" value={String(routeCorrelation?.repositoryRouteCount??0)} detail="Literal source declarations"/><Metric label="PATH OVERLAPS" value={String(routeCorrelation?.matches.length??0)} detail="Medium / low confidence"/></div>{routeCorrelation?.matches.length?<>{routeCorrelation.matches.map((match,index)=><button className="security-row" key={match.websitePath+"-"+match.repositoryRoute.source_path+"-"+match.repositoryRoute.line+"-"+index} onClick={()=>setDetail({title:match.websiteMethod?match.websiteMethod+" "+match.websitePath:match.websitePath,body:"Website evidence: "+match.websiteEvidence+"\nSource: "+match.websiteSource+(match.websiteLine?"\nLine: "+match.websiteLine:"")+"\n\nRepository route: "+match.repositoryRoute.method+" "+match.repositoryRoute.path+"\nSource: "+match.repositoryRoute.source_path+":"+match.repositoryRoute.line+"\nSyntax: "+match.repositoryRoute.syntax+"\n\nMatch: "+match.matchKind+"\nConfidence: "+match.confidence+"\n\n"+match.explanation+"\n\nThis overlap does not establish deployment identity, reachability, access control, or exploitability."})}><em className={match.confidence}>{match.confidence.toUpperCase()}</em><span><b>{match.websiteMethod??"METHOD UNKNOWN"} {match.websitePath}</b><small>{match.websiteEvidence} ↔ {match.repositoryRoute.source_path}:{match.repositoryRoute.line} · {match.repositoryRoute.method} {match.repositoryRoute.path}</small></span><ArrowUpRight size={14}/></button>)}</>:<p className="quiet">No literal route overlaps were found by the configured comparison. Dynamic routing and incomplete crawl/source coverage can hide real relationships.</p>}{routeCorrelation&&routeCorrelation.unmatchedWebsitePaths.length>0&&<><div className="subhead">Website paths without a source match</div>{routeCorrelation.unmatchedWebsitePaths.slice(0,100).map(path=><div className="dependency-row" key={path}><span><b>{path}</b><small>No matching route declaration was found in the supplied inventory</small></span></div>)}</>}{routeCorrelation&&routeCorrelation.unmatchedRepositoryRoutes.length>0&&<><div className="subhead">Repository routes not observed on the website</div>{routeCorrelation.unmatchedRepositoryRoutes.slice(0,100).map((route,index)=><div className="dependency-row" key={route.method+"-"+route.path+"-"+route.source_path+"-"+route.line+"-"+index}><span><b>{route.method} {route.path}</b><small>{route.source_path}:{route.line} · not observed in this website scan</small></span></div>)}</>}{routeCorrelation?.truncated&&<p className="notice">The repository route inventory or correlation result reached a configured limit. Some relationships may be omitted.</p>}<Panel title="Interpretation limits" badge="IMPORTANT" icon={<CircleAlert size={15}/>}>{routeCorrelation?.notes.map((note,index)=><p className="notice" key={index}>{note}</p>)}</Panel></>}</Panel></div>:!scan?<div className="empty"><div className="empty-icon"><Layers3 size={28}/></div><label>{busy?"ANALYSIS IN PROGRESS":"READY FOR ANALYSIS"}</label><h2>{busy?"Inspecting observable website data":"Start with a website URL"}</h2><p>{busy?"Fetching a bounded response and extracting public metadata.":"Enter a URL you own or have permission to inspect. UnWeb labels heuristic results and reports evidence."}</p><div className="checks"><span><Check size={13}/> HTTP metadata</span><span><Check size={13}/> Public assets</span><span><Check size={13}/> Passive checks</span></div></div>:<>
 {tab==="Overview"&&<div className="stack"><div className="metrics"><Metric label="HTTP STATUS" value={String(scan.status_code)} detail="Observed response"/><Metric label="PAGES DISCOVERED" value={String(scan.pages.length)} detail="Bounded same-origin crawl"/><Metric label="PUBLIC ASSETS" value={String(scan.assets.length)} detail="Scripts, styles, images"/><Metric label="PASSIVE FINDINGS" value={String(scan.findings.length)} detail="Review evidence"/></div><Panel title="Target intelligence" badge="OBSERVED RESPONSE" icon={<Globe2 size={15}/>}><div className="target-info"><div className="site-icon"><Globe2 size={20}/></div><div><h2>{scan.title||scan.final_url}</h2><a href={scan.final_url} target="_blank" rel="noreferrer">{scan.final_url} <ArrowUpRight size={12}/></a><p>{scan.description||"No meta description was found in the inspected HTML."}</p></div></div><div className="details">{[["Final URL",scan.final_url],["HTTP status",String(scan.status_code)],["Scanned at",new Date(scan.scanned_at).toLocaleString()],["HTML title",scan.title||"Not present"]].map(([k,v])=><div key={k}><small>{k}</small><b title={v}>{v}</b></div>)}</div></Panel><div className="two"><Panel title="Technology fingerprints" badge={`${scan.technologies.length} SIGNALS`} icon={<Code2 size={15}/>}>{scan.technologies.length?scan.technologies.map(t=><div className="row" key={t.name}><Braces size={15}/><span><b>{t.name}</b><small>{t.evidence}</small></span><em>{t.confidence}</em></div>):<p className="quiet">No configured fingerprint matched. That does not prove a framework is absent.</p>}</Panel><Panel title="Security overview" badge="PASSIVE" icon={<ShieldCheck size={15}/>}>{scan.findings.slice(0,5).map(f=><button className="finding" key={f.id} onClick={()=>{setTab("Security");setDetail({title:f.title,body:`${f.evidence}\n\nRecommendation: ${f.recommendation}`})}}><i className={f.severity}/>{f.title}<ArrowUpRight size={13}/></button>)}{!scan.findings.length&&<p className="quiet">No findings were generated by configured checks.</p>}</Panel></div><Panel title="Discovered assets" badge={`${assets.length} RESOURCES`} icon={<FileCode2 size={15}/>}><div className="filter"><Search size={14}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Filter by type or URL…"/><small>{assets.length} shown</small></div><div className="table-head"><span>TYPE</span><span>RESOURCE URL</span><span></span></div>{assets.slice(0,100).map((a,i)=><button className="asset" key={`${a.url}-${i}`} onClick={()=>setDetail({title:a.kind,body:a.url})}><span>{a.kind}</span><code>{a.url}</code><ArrowUpRight size={13}/></button>)}{!assets.length&&<p className="quiet">No matching assets.</p>}</Panel></div>}
 {tab==="Sitemap"&&<Panel title="Discovered pages" badge={`${scan.pages.length} NODES`} icon={<Network size={15}/>}><SitemapGraph pages={scan.pages} edges={scan.edges.filter(e=>scan.pages.some(p=>p.url===e.source)&&scan.pages.some(p=>p.url===e.target))}/><p className="notice">Pages are discovered breadth-first from same-origin links. The relationships below are links directly observed in fetched HTML; this is not guaranteed to be a complete sitemap.</p>{scan.edges.filter(e=>scan.pages.some(p=>p.url===e.source)&&scan.pages.some(p=>p.url===e.target)).length>0&&<div className="observed-edges"><div className="table-head"><span>OBSERVED RELATIONSHIPS</span><span>SOURCE → TARGET</span><span></span></div>{scan.edges.filter(e=>scan.pages.some(p=>p.url===e.source)&&scan.pages.some(p=>p.url===e.target)).map((e,i)=><div className="edge-row" key={`${e.source}-${e.target}-${i}`}><span>{scan.pages.find(p=>p.url===e.source)?.title||new URL(e.source).pathname}</span><span>→</span><span>{scan.pages.find(p=>p.url===e.target)?.title||new URL(e.target).pathname}</span></div>)}</div>}{scan.pages.map((p,i)=><button className="page-row" key={p.url} onClick={()=>setDetail({title:p.title||p.url,body:`${p.url}\n\nLinks: ${p.links.length}\nScripts: ${p.scripts.length}`})}><code>{String(i+1).padStart(2,"0")}</code><span><b>{p.title||"(untitled page)"}</b><small>{p.url}</small></span><em>{p.status_code??"—"}</em><ArrowUpRight size={13}/></button>)}</Panel>}
 {tab==="JavaScript"&&<Panel title="JavaScript intelligence" badge={`${scan.js_analysis.length} SCRIPTS`} icon={<Braces size={15}/>}><p className="notice">Comment-aware lexical clues from delivered scripts. These are not AST analysis and do not prove routes are active, dependencies execute, or source maps are accessible.</p>{scan.js_analysis.map((j,i)=><div className="js-item" key={j.url||i}><b>{j.url||"Script"}</b>{j.error?<p>{j.error}</p>:<><p>{(j.bytes_analyzed??0).toLocaleString()} bytes · {j.line_count??"—"} lines · Possible libraries: {j.possible_libraries?.join(", ")||"None matched"}</p><div className="js-evidence-list"><label>ROUTE REFERENCES</label>{(j.route_references?.length?j.route_references:j.routes?.map(url=>({url,line:0,confidence:"medium" as const,context:"route-like-string",dynamic_template_prefix:false,evidence:"Legacy route clue",method:undefined}))||[]).map((route,index)=><button className="js-evidence" key={`${route.url}-${index}`} onClick={()=>setDetail({title:`${route.method||"PATH"} ${route.url}`,body:`Line: ${route.line||"not recorded"}\nConfidence: ${route.confidence}\nContext: ${route.context}\nDynamic template prefix: ${route.dynamic_template_prefix?"yes":"no"}\n\nSource evidence:\n${route.evidence}`})}><code>{route.method||"PATH"} {route.url}</code><span>line {route.line||"—"} · {route.confidence}</span></button>)}{!j.route_references?.length&&!j.routes?.length&&<p className="quiet">No route-like references found.</p>}</div>{Array.isArray(j.library_evidence)&&j.library_evidence.length>0&&<div className="js-evidence-list"><label>LIBRARY MARKERS</label>{j.library_evidence.map((item,index)=><button className="js-evidence" key={`${item.name}-${index}`} onClick={()=>setDetail({title:`${item.name} marker`,body:`Confidence: ${item.confidence}\nOffset: ${item.offset}\n\nObserved source:\n${item.evidence}`})}><code>{item.name}</code><span>{item.confidence} evidence</span></button>)}</div>}{Array.isArray(j.source_map_references)&&j.source_map_references.length>0&&<div className="js-evidence-list"><label>SOURCE MAP REFERENCES</label>{j.source_map_references.map((item,index)=><button className="js-evidence" key={`${item.reference}-${index}`} onClick={()=>setDetail({title:"Source map reference",body:`${item.reference}\nLine: ${item.line}\n\nA reference in a comment does not prove the source map is reachable.`})}><code>{item.reference}</code><span>line {item.line}</span></button>)}</div>}{!j.source_map_references?.length&&<p className="quiet">No source-map comment was observed.</p>}</>}</div>)}{!scan.js_analysis.length&&<p className="quiet">No same-origin JavaScript bundle was available for analysis.</p>}</Panel>}
 {tab==="Security"&&<div className="stack"><Panel title="Security evidence" badge={`${webEvidence.length} FINDINGS`} icon={<ShieldCheck size={15}/>}><p className="notice">Severity and confidence are separate. Website response facts are marked observed; repository patterns are marked suspected until independently validated. Neither state alone proves exploitability.</p>{webEvidence.map(f=><button className="security-row" key={f.finding_id} onClick={()=>setDetail({title:f.title,body:`Source: ${f.source}\nRule: ${f.check_id}\nSeverity: ${f.severity}\nConfidence: ${f.confidence}\nValidation: ${f.validation_state}\nLocation: ${findingLocation(f)}\n\nEvidence:\n${f.evidence}\n\nImpact: ${f.impact||"Not established"}\nPreconditions: ${f.preconditions.length?f.preconditions.join(", "):"Not established"}\n\nRemediation:\n${f.remediation}`})}><em className={f.severity}>{f.severity.toUpperCase()}</em><span><b>{f.title}</b><small>{findingLocation(f)} · {f.validation_state} · {f.confidence} confidence</small></span><ArrowUpRight size={14}/></button>)}{!webEvidence.length&&<p className="quiet">No findings were generated by configured checks. This is not a proof that the target is secure.</p>}</Panel><Panel title="Observed response headers" badge={`${Object.keys(scan.headers).length} HEADERS`} icon={<LockKeyhole size={15}/>}>{Object.entries(scan.headers).map(([k,v])=><div className="header-row" key={k}><code>{k}</code><span>{v}</span></div>)}</Panel></div>}
 {tab==="Reconstruction"&&<div className="stack"><Panel title="Reconstruction Studio" badge="GENERATED STARTER" icon={<Layers3 size={15}/>}><p className="notice">Generated from observed headings and text. It does not recover private source code or guarantee pixel-perfect similarity. Review content and rights before publishing.</p><div className="split"><div><div className="subhead"><Code2 size={13}/> App.tsx <small>TSX</small></div><pre>{scan.reconstruction?.["App.tsx"]||"// No reconstruction generated"}</pre></div><div className="preview"><label>SANDBOXED HTML PREVIEW</label>{scan.reconstruction?.["preview.html"]?<iframe className="rebuild-frame" title="Generated website reconstruction preview" srcDoc={scan.reconstruction["preview.html"]} sandbox="" loading="lazy"/>:<p>Preview is unavailable for this scan.</p>}<small>STATIC PREVIEW · SCRIPTS DISABLED · EXTERNAL IMAGES MAY LOAD</small></div></div><div className="rebuild-downloads"><button className="download-code" onClick={()=>download(scan.reconstruction?.["App.tsx"]||"","App.tsx")}> <Download size={14}/> Download App.tsx</button><button className="download-code" onClick={()=>download(scan.reconstruction?.["preview.html"]||"","preview.html","text/html")}> <Download size={14}/> Download preview</button><button className="download-code" onClick={()=>download(scan.reconstruction?.["reconstruction-manifest.json"]||"{}","reconstruction-manifest.json","application/json")}> <Download size={14}/> Download manifest</button></div></Panel><Panel title="Generated files" badge={`${Object.keys(scan.reconstruction||{}).length} FILES`} icon={<FileCode2 size={15}/>}>{Object.entries(scan.reconstruction||{}).map(([name,body])=><button className="file" key={name} onClick={()=>setDetail({title:name,body})}><FileCode2 size={14}/>{name}<span>View source <ArrowUpRight size={12}/></span></button>)}</Panel></div>}
 </>}
 <footer className="footer"><span>UNWEB · PASSIVE WEB INTELLIGENCE</span><span>FACTS FIRST. INFERENCES LABELLED.</span></footer></main></div>
 {detail&&<div className="backdrop" onClick={()=>setDetail(null)}><aside className="drawer" onClick={e=>e.stopPropagation()}><header><div><small>EVIDENCE DETAIL</small><h2>{detail.title}</h2></div><button className="icon" onClick={()=>setDetail(null)}><X size={16}/></button></header><pre>{detail.body}</pre><button className="download-code" onClick={()=>download(detail.body,"unweb-evidence.txt")}> <Download size={14}/> Export evidence</button></aside></div>}</div>;
}

export function BrowserEvidence({result}:{result:BrowserRenderResult}){
 const requests=result.network?.requests||[],responses=result.network?.responses||[],failures=result.network?.failed_requests||[],headings=result.dom?.headings||[],links=result.dom?.links||[],images=result.dom?.images||[];
 return <div className="browser-evidence">
  <div><h3>{result.title||result.dom?.title||"Rendered page"}</h3><p className="quiet">{result.final_url} · {result.engine} · HTTP {result.navigation_status??"unknown"}{result.navigation_error_type?` · ${result.navigation_error_type}`:""}</p>{result.dom?.description&&<p className="quiet">{result.dom.description}</p>}</div>
  <div className="browser-evidence-metrics"><div><small>REQUESTS</small><b>{result.network?.request_count??0}</b></div><div><small>BLOCKED</small><b>{result.network?.blocked_request_count??0}</b></div><div><small>PAGE ERRORS</small><b>{result.browser_errors?.page_error_count??0}</b></div><div><small>CONSOLE ERRORS</small><b>{result.browser_errors?.console_error_count??0}</b></div><div><small>WEBSOCKETS</small><b>{result.network?.websockets?.length??0}</b></div><div><small>IMAGES</small><b>{images.length}</b></div><div><small>DECLARED BYTES</small><b>{(result.network?.declared_response_bytes??0).toLocaleString()}</b></div></div>
  <section className="browser-evidence-block"><header>DOM headings · {headings.length}</header><pre>{headings.length?headings.map(item=>`${"#".repeat(Math.max(1,Math.min(item.level,6)))} ${item.text}`).join("\n"):"No headings captured."}</pre></section>
  <section className="browser-evidence-block"><header>Network requests · {requests.length}</header><pre>{requests.length?requests.map(item=>`${item.method} · ${item.resource_type} · ${item.url}`).join("\n"):"No request paths captured."}</pre></section>
  <section className="browser-evidence-block"><header>Network responses · {responses.length}</header><pre>{responses.length?responses.map(item=>`${item.status} · ${item.content_type||"unknown"} · ${item.url}`).join("\n"):"No response records captured."}</pre></section>
  <section className="browser-evidence-block"><header>Observed same-origin links · {links.length}</header><pre>{links.length?links.map(item=>`${item.text||"(no link text)"} · ${item.url}`).join("\n"):"No same-origin links captured."}</pre></section>
  <section className="browser-evidence-block"><header>Failed requests · {failures.length}</header><pre>{failures.length?failures.map(item=>`${item.resource_type} · ${item.url}`).join("\n"):"No failed requests captured."}</pre></section>
  <section className="browser-evidence-block"><header>Same-origin assets</header><pre>{[...(result.dom?.stylesheetLinks||[]).map(url=>"CSS · "+url),...(result.dom?.scriptLinks||[]).map(url=>"JS · "+url),...images.map(item=>"IMG · "+item.url) ].join("\n")||"No assets captured."}</pre></section>
  {result.browser_errors&&<section className="browser-evidence-block"><header>Runtime diagnostics</header><pre>{JSON.stringify(result.browser_errors,null,2)}</pre></section>}
  <section className="browser-evidence-block"><header>Worker limitations</header><pre>{(result.limitations||[]).join("\n")}</pre></section>
  <button type="button" className="download-code" onClick={()=>{const blob=new Blob([JSON.stringify(result,null,2)],{type:"application/json"});const anchor=document.createElement("a");anchor.href=URL.createObjectURL(blob);anchor.download="unweb-browser-evidence.json";anchor.click();window.setTimeout(()=>URL.revokeObjectURL(anchor.href),1000);}}><Download size={13}/> Export browser evidence JSON</button>
 </div>;
}

function Metric({label,value,detail}:{label:string;value:string;detail:string}){return <div className="metric"><small>{label}</small><b>{value}</b><span>{detail}</span></div>}
function Panel({title,badge,icon,children}:{title:string;badge:string;icon:ReactNode;children:ReactNode}){return <section className="panel"><header><div>{icon}<b>{title}</b></div><small>{badge}</small></header>{children}</section>}
